              "id": "a3_s4_c13_l1",
              "original": "Alors je vous demanderai la permission de m’en aller… J’ai consenti à vous servir de guide parce que vous m’avez bien payé ; mais maintenant que vous êtes arrivée… si ça ne vous fait rien, j’irai vous attendre là où vous m’avez pris… à l’auberge qui est au bas de la montagne.",
              "literal": "Then I will ask you permission to go away... I consented to serve as your guide because you paid me well; but now that you have arrived... if it makes no difference to you, I will go wait for you where you took me... at the inn which is at the foot of the mountain.",
